INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (8294, '<沙塔尔.碎颅发出兴奋的怒吼。>$B$B他们还能支撑多久?还要牺牲多少联盟的渣滓才能让他们退却?只有时间可以说明一切，$r……') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (8297, '你拿到资源了!干得好!我会把这些资源送到我们的军需官那里，然后让他迅速把它们配置给我们的军队。$B$B谢谢你，$N。事实上，不断地完成这样的任务将是获得最终胜利的关键要素。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
