INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8042, '见到你身体健康真好，$N。这场显赫的战斗影响着这个星球上的所有生物。绝不能让哈卡离开祖尔格拉布，否则世界将会毁在他无尽的欲望中。$B$B把坠饰给我吧，我会强化它的力量。运用穆贾巴之力惩罚我们的敌人吧!') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8043, '见到你身体健康真好，$N。这场显赫的战斗影响着这个星球上的所有生物。绝不能让哈卡离开祖尔格拉布，否则世界将会毁在他无尽的欲望中。$B$B把坠饰给我吧，我会强化它的力量。运用穆贾巴之力惩罚我们的敌人吧!') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8044, '拉斯塔哈向你致敬，$N。这样的荣誉对非赞达拉部族的成员来说还是头一次。$B$B<金罗克向你鞠躬。>$B$B把坠饰给我吧，我会再次强化它的力量。穆贾巴的怒火已经与你的灵魂连在了一起。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8046, '我的判断看来有些草率，$C。似乎你对圣光的盲目信仰还有些用处。$B$B把烙印给我吧，我会强化它的力量。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8047, '我的判断看来有些草率，$C。似乎你对圣光的盲目信仰还有些用处。$B$B把烙印给我吧，我会强化它的力量。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8050, '牧师，你与古拉巴什一族作战的英勇事迹早已家喻户晓，就连皇室成员也开始谈论你的故事。据说拉斯塔哈甚至提到了你的名字。$B$B现在是为祖达萨之眼注入魔法的时候了。把坠饰交给我吧。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8051, '牧师，你与古拉巴什一族作战的英勇事迹早已家喻户晓，就连皇室成员也开始谈论你的故事。据说拉斯塔哈甚至提到了你的名字。$B$B现在是为祖达萨之眼注入魔法的时候了。把坠饰交给我吧。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8052, '$N，如果我们有上万名像你这样的人物，哈卡的军队将在瞬间灰飞烟灭。$B$B<阿塔比姆发出了一声叹息。>$B$B唉，祖达萨之眼就要发挥它所有的潜能了。把它给我。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8054, '你获胜了?你取回权力珍宝了吗?你杀死敌人了吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8080, '你拿到资源木箱了吗，$N?如果没有足够的资源，阿拉索联军的士兵可没有办法好好干一仗……') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8081, '虽然在破坏阿拉索联军的补给线方面，污染者做得已经很不错了，但是联盟还在继续对阿拉希盆地进行攻击。我们必须向盆地增派部队，并夺回更多的资源。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8102, '欢迎回来，$c。我能发现卡亚罗之石有了变化。很多敌人都栽在你那超凡的能力下了。他们罪有应得。是该让我提升石头的能力了。把它拿给我。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8113, '$N!好久不见。拉斯塔哈命令我为你的坠饰加入更多的魔精和魔法，这可是最后一次呢，你知道吗?真的!要不是亲眼所见，我怎么都无法相信呢。把坠饰放在这儿吧。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8118, '啊哈!梅维基闹了一个笑话!$B$B<梅维基大笑。>$B$B这么说，你一直利用灵魂和元素的力量对抗那些藏在祖尔格拉布的敌人，是吗?这值得奖励!$B$B梅维基会磨亮你的宝珠的。把宝珠放在这儿，$N。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8124, '虽然在破坏阿拉索联军的补给线方面，污染者做得已经很不错了，但是联盟还在继续对阿拉希盆地进行攻击。我们必须向盆地增派部队，并夺回更多的资源。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8144, '$N，它渴望成长。坠饰已经吸取了祖尔格拉布上千具巨魔尸体的能量。把它给我吧，我会对它做最后一次强化。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8148, '莫托尔替拉斯塔哈传话给你，$N。皇室对你全力剿灭哈卡军队的行为倍加赞赏。我会在坠饰中编入最后一根漩涡之藤的。把它给我吧。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8154, '你拿到资源木箱了吗，$N?如果没有足够的资源，阿拉索联军的士兵可没有办法好好打一仗……') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
