INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8492, '你收集好那20个铜锭了吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8493, '又回来了$C?太好了!我们还需要大量的铜锭，为了准备安其拉之战，请尽你所能地帮我收集铜锭，这些铜锭是要用来建造蒸汽坦克跟旋翼机，$B$B我们为了安其拉战役，真的还需要更多铜锭，你愿意帮帮我们吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8494, '如果你收集到那20个铁锭，我可不想发现你把它们都藏起来了!') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8495, '这么快就回来了?不要让我再重新评估对你不好的看法$C，你让我觉得很感伤。那么，你知道我们仍然没有足够的铁锭供应武器、护甲、蒸汽坦克和搜寻故障所有需要的东西。你觉得你可以在去祖尔格拉布的路上，或是你们这些孩子现在鬼混的地方带回另一批20个铁锭吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8499, '我希望你已经成功收集好我们之前讲的瑟银锭了。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8500, '能再见到你真好，$N。希望你一切都好。我们现在还需要瑟银锭。如果你有的\\r\n话请分给我，我正在为安其拉之战收集。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8503, '这不是真的!我从来没有将这些堆积物上面的荆棘藻去除过。有人可能会认为它几乎就是经济利义下有效的万灵丹。*咳咳*你不会正好有我们先前谈的荆棘藻吧?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8505, '你有我要的紫莲花草药了吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8509, '那是什么?大声的说出来，$C!你拿到我要的阿尔萨斯之泪吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8514, '是的$g先生:女士;，看来当前我们已经收集了很多中皮。但我们需要更多的中皮。我可以向你保证这很好用;一块也不要浪费。我知道这个数量很庞大，但如果你愿意，我可以藉由你的帮忙让我的配额减少一点。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8516, '没错，存货仍然不够。$N，我们仍未达到理想的目标。想想我们能用重皮做的所有东西!各种护甲和武器。蒸汽坦克的零件和步枪瞄准器!工程学护目镜，而且如果到最后我们还有剩下，可以把它们交给部落的齐柏林飞艇!$B$B你会为我带更多的重皮回来吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8518, '我对于你在私下还有如此无私的行为感到很惊讶。$C，在我的任务完成之前我仍需要一些亚麻布绷带。你能再次帮我收集那些绷带吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8520, '你好，$C，你拿到那20个丝质绷带了吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8523, '又是讨论紧急事件的时候了，$C。我再次感谢你之前所作的努力;不是每个人都能如此无私奉献。但是我们仍然很多事要完成。$B$B$N，你可以再去收集符文布绷带并拿回来这里给我吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8526, '你拿到所有的烤迅猛龙肉了吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8528, '我有信心你很快就会带着我们讨论的斑点黄尾鱼回来。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8529, '如果你愿意我想派你再去捕一批斑点黄尾鱼，$N。我想你有了第一次的经验，这次捕鱼一定会更快更容易。你愿意吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8533, '这么快就回来了?你很快就会成为一个真正的矿工了$C。那么，你已经知道怎么钻孔了;我需要你出去帮我挖掘一堆铜矿，熔解它们做成铜锭再带回来给我。我知道你能办到，问题是，你愿意吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8543, '很好，我看的出你对这场战争很用心。我有点期盼战争可以赶快开始，我想你应该也是一样，$C。当战争开始时一定会是很光荣的。部落这在希利苏斯沙漠的尘土上奔驰着，手上拿着武器，冲锋陷阵在无数的虫群之中。总有一天将会取得极大的荣耀!$B$B哈!但是首先我们需要锡锭。真有趣，这样的小东西却可以带来巨大的不同，你说不是吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8578, '熔火之心啊?我希望我的护目镜还完好如初!') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8580, '你不想让比雷凯基生气吧。要让比雷凯基高兴，你就得快速地带给他很多的火焰花。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8582, '你已经带着我要的紫莲花回来了吗，$C?你一定得尽快做好这件事，否则我这里要做的事全是空谈。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8626, '你拿到我所需要的东西了吗，$N?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8656, '在安其拉的住所里，可怕的克苏恩在睡眠中等待着。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8657, '你把我所要求的材料都带回来了吗， $N?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8659, '你收集好我要的材料了吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8666, '在安其拉的住所里，可怕的克苏恩在睡眠中等待着。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8743, '甲虫之锣嗡嗡作响，给你一种不安的感觉。坚强起来，$N。一旦甲虫之锣被敲响，安其拉的大门就将被打开。$B$B从这扇大门之后涌出来的将会是混乱和毁灭。保护你的人民!') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8748, '你一直保护卡利姆多生灵的行为已经被我们认可。把徽记之戒拿来，让我增强它的能量。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8749, '向你致敬，$N。粉碎卡利姆多的敌人！告诉他们污染这片不灭星光照耀下的大陆要付出什么代价！$b$b你又赢得了一个强效施法。请把徽记之戒给我，我来灌注能量。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8750, '如此巨大的奉献真是少有。你已证明了你的意志坚定，$N。你会因为勇敢的守护着我们的世界而获得重赏。$B$B请将你的徽记之戒交给我，这样我才能强化它的能量。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8757, '相当出色，小家伙。你吃了不少苦才获得青铜龙军团的青睐。你的奉献令人印象深刻。$B$B塑能师的徽记之戒将会大大提升你的魔法和自然能力。$B$B提高警觉，一旦你选择了你的道路，就无法回头了。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8758, '你一直保护卡利姆多生灵的行为已经被我们认可。把徽记之戒拿来，让我增强它的能量。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8760, '如此巨大的奉献真是少有。你已证明了你的意志坚定，$N。你会因为勇敢的守护着我们的世界而获得重赏。$B$B请将你的徽记之戒交给我，这样我才能强化它的能量。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8765, '勇士，如果你决定走上另一条道路，请将你的徽记之戒交给我并从我们的安其拉敌人那里带回一堆甲虫。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8766, '勇士，如果你决定走上另一条道路，请将你的徽记之戒交给我并从我们的安其拉敌人那里带回一堆甲虫。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8790, '你会将他们击败并让我们脱离这些束缚。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8843, '完成了自己的任务并得到荣誉徽章的冒险者可以把他们的徽章交给我，你每次把10枚徽章交给我，我都可以用它们来显着提升你在暴风城的声望。当然，我也接受单枚徽章的交换申请，但是这对于声望的提升效果就会逊色许多。虽然我们不会忘记每一位冒险者的努力，但是贡献越大，回报就越大。$B$B如果你有足够的荣誉徽章要给我的话，随时来找我。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8845, '完成了自己的任务并得到荣誉徽章的冒险者可以把他们的徽章交给我，你每次把10枚徽章交给我，我都可以用它们来显着提升你在暴风城的声望。当然，我也接受单枚徽章的交换申请，但是这对于声望的提升效果就会逊色许多。虽然我们不会忘记每一位冒险者的努力，但是贡献越大，回报就越大。$B$B如果你有足够的荣誉徽章要给我的话，随时来找我。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8904, '我的担心是对的吗?我们的白痴守卫克服了没?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8992, '我欣赏你，$N，如果你能带着完整的护符回来的话。如果没有，那么，请快点完成别浪费时间，我向你保证!') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8999, '依照我们的约定，你准备好交出你的野性之心装备来换取全新的野兽之心风帽和外衣了吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (9022, '你回来了，我从你的眼睛里看出来你有很多话想跟我讲，$N。让我们先处理好你的奖励。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (9042, '手腕是全身第二脆弱的部位……还是第四个?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (9050, '如果你要我帮你制作护甲就一定要将我说的东西带来。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (9061, '你有我要的物品了吗，$C?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (9075, '你把我要的东西带来了吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (9081, '赶快把材料带给我不要再浪费我的时间了，$C。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (9093, '材料虽然昂贵，但你很快就不会放在心上了。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (9367, '火焰都发烫着吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (9388, '庆典结束之前火焰都不能熄灭!') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
